# Strip line numbers from original
stripped_original = '\n'.join(
    re.sub(r'^\s*\d+\t', '', line) for line in original.split('\n')
)

# Find all top-level function definitions in original
orig_funcs = []
for i, line in enumerate(stripped_original.split('\n')):
    if re.match(r'^def [a-z]', line):
        orig_funcs.append(line.strip())
print("Top-level functions in original:")
for f in orig_funcs:
    print(f"  {f}")

# Find all top-level function definitions in new_content
